#include <iostream>
#include <string>
#include <iomanip>

class CommissionEmployeeProtected {
protected:
    std::string firstName;
    std::string lastName;
    std::string ssn;
    double grossSales;
    double commissionRate;

public:
    CommissionEmployeeProtected(const std::string& first, const std::string& last,
                                const std::string& ssnVal, double sales, double rate)
        : firstName(first), lastName(last), ssn(ssnVal),
          grossSales(sales), commissionRate(rate) {}

    double earnings() const { return grossSales * commissionRate; }
};

class FlawedDerived : public CommissionEmployeeProtected {
public:
    FlawedDerived(const std::string& first, const std::string& last,
                  const std::string& ssnVal, double sales, double rate)
        : CommissionEmployeeProtected(first, last, ssnVal, sales, rate) {}

    void corruptState() {
        // Bypasses validation due to protected access
        grossSales = -1000.0;
        commissionRate = -0.5;
    }

    void print() const {
        std::cout << firstName << " " << lastName
                  << " SSN: " << ssn
                  << " Sales: " << grossSales
                  << " Rate: " << commissionRate
                  << " Earnings: " << earnings() << "\n";
    }
};

int main() {
    FlawedDerived emp("Bob", "Lewis", "333-33-3333", 5000.0, 0.04);
    std::cout << std::fixed << std::setprecision(2);
    emp.print();
    emp.corruptState();
    emp.print();
    return 0;
}

#include <iostream>
#include <string>
#include <stdexcept>
#include <iomanip>

class CommissionEmployee {
private:
    std::string firstName;
    std::string lastName;
    std::string socialSecurityNumber;
    double grossSales;
    double commissionRate;

public:
    CommissionEmployee(const std::string& first, const std::string& last,
                       const std::string& ssn, double sales = 0.0, double rate = 0.0)
        : firstName(first), lastName(last), socialSecurityNumber(ssn) {
        setGrossSales(sales);
        setCommissionRate(rate);
    }

    void setFirstName(const std::string& first) { firstName = first; }
    std::string getFirstName() const { return firstName; }

    void setLastName(const std::string& last) { lastName = last; }
    std::string getLastName() const { return lastName; }

    void setSocialSecurityNumber(const std::string& ssn) { socialSecurityNumber = ssn; }
    std::string getSocialSecurityNumber() const { return socialSecurityNumber; }

    void setGrossSales(double sales) {
        if (sales >= 0.0) grossSales = sales;
        else throw std::invalid_argument("Gross sales must be >= 0.0");
    }
    double getGrossSales() const { return grossSales; }

    void setCommissionRate(double rate) {
        if (rate > 0.0 && rate < 1.0) commissionRate = rate;
        else throw std::invalid_argument("Commission rate must be > 0.0 and < 1.0");
    }
    double getCommissionRate() const { return commissionRate; }

    double earnings() const {
        return getCommissionRate() * getGrossSales();
    }

    void print() const {
        std::cout << "commission employee: " << getFirstName() << ' ' << getLastName()
                  << "\nsocial security number: " << getSocialSecurityNumber()
                  << "\ngross sales: " << getGrossSales()
                  << "\ncommission rate: " << getCommissionRate() << "\n";
    }
};

int main() {
    try {
        CommissionEmployee emp("Bob", "Lewis", "333-33-3333", 5000.0, 0.04);
        std::cout << std::fixed << std::setprecision(2);
        emp.print();
        std::cout << "Earnings: $" << emp.earnings() << "\n";

        // Testing validation safeguard
        emp.setGrossSales(-50.0);
    } catch (const std::invalid_argument& ex) {
        std::cout << "Caught expected exception: " << ex.what() << "\n";
    }
    return 0;
}
